// ScrollVars fx · sequenced-scrub
// Requires: npm i scrollvars · import 'scrollvars/styles/pin.css' (layout)
// Each child animates over its own slice of the pin: pass ranges as
// [from, to] pairs (0..1); overlapping ranges are fine: that's the point.
'use client'
import * as React from 'react'
import { Track } from 'scrollvars/react'

export function SequencedScrub({
  children,
  ranges,
  height = '250vh',
  className,
}: {
  children: React.ReactNode
  /** One [from, to] per child; defaults to evenly staggered overlapping slices. */
  ranges?: [number, number][]
  height?: string
  className?: string
}) {
  // toArray, not Children.map: a conditional step ({show && <Card/>}) is
  // false, and Children.map still calls back for it, so the stack got an
  // empty slice and every step after it scrubbed on the wrong window.
  // Anything that is not an element (a portal renders elsewhere) passes
  // through: it owns no slice of the pin.
  const items = React.Children.toArray(children)
  const count = items.filter(React.isValidElement).length
  let step = -1
  return (
    <Track pin={height} className={className}>
      <div className="sv-stage" style={{ display: 'grid', placeItems: 'center' }}>
        <div className="sv-range sv-range-rise" style={{ display: 'grid', gap: 12 }}>
          {items.map((child) => {
            if (!React.isValidElement(child)) return child
            const i = ++step
            const [from, to] = ranges?.[i] ?? [i / count, Math.min((i + 1.6) / count, 1)]
            return (
              <div key={child.key} style={{ '--sv-from': from, '--sv-to': to } as React.CSSProperties}>
                {child}
              </div>
            )
          })}
        </div>
      </div>
    </Track>
  )
}

// ScrollVars fx · gsap-scrub
// Requires: npm i scrollvars gsap · import 'scrollvars/styles/pin.css'
// Author choreography in GSAP, let ScrollVars drive it: one scroll
// listener, one writer. Never ALSO create a ScrollTrigger for it.
// Honesty: this page pays GSAP's bundle. Adopt per page, not globally.
'use client'
import * as React from 'react'
import gsap from 'gsap'
import { prefersReducedMotion } from 'scrollvars'
import { Track } from 'scrollvars/react'

export function GsapScrub({
  children,
  buildTimeline,
  height = '250vh',
  className,
}: {
  children: React.ReactNode
  /** Build and return a PAUSED timeline over the given stage element. */
  buildTimeline: (stage: HTMLDivElement) => gsap.core.Timeline
  height?: string
  className?: string
}) {
  const stage = React.useRef<HTMLDivElement>(null)
  const tl = React.useRef<gsap.core.Timeline | null>(null)
  const progress = React.useRef(0)
  React.useEffect(() => {
    if (stage.current) {
      tl.current = buildTimeline(stage.current)
      tl.current.progress(prefersReducedMotion() ? 1 : progress.current)
    }
    return () => { tl.current?.kill() }
  }, [buildTimeline])
  return (
    <Track
      pin={height}
      onPin={(p) => { progress.current = p; tl.current?.progress(prefersReducedMotion() ? 1 : p) }}
      className={className}
    >
      <div ref={stage} className="sv-stage" style={{ display: 'grid', placeItems: 'center' }}>
        {children}
      </div>
    </Track>
  )
}

// ScrollVars fx · three-scene
// Requires: npm i scrollvars three · import 'scrollvars/styles/pin.css'
// The canvas harness owns the lifecycle (DPR, resize, pause offscreen,
// reduced motion, cleanup); Three owns the rendering; scroll feeds progress.
'use client'
import * as React from 'react'
import * as THREE from 'three'
import { Track, useCanvasEffect } from 'scrollvars/react'

export function ThreeScene({ height = '250vh', className }: { height?: string; className?: string }) {
  const progress = React.useRef(0)
  const three = React.useRef<{ renderer: THREE.WebGLRenderer; scene: THREE.Scene; camera: THREE.PerspectiveCamera; mesh: THREE.Mesh } | null>(null)

  const canvasRef = useCanvasEffect({
    context: null, // WebGL owns the canvas
    setup(fx) {
      const renderer = new THREE.WebGLRenderer({ canvas: fx.canvas, alpha: true, antialias: true })
      const scene = new THREE.Scene()
      const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100)
      const mesh = new THREE.Mesh(
        new THREE.TorusKnotGeometry(1.1, 0.34, 160, 24),
        new THREE.MeshNormalMaterial({ wireframe: true })
      )
      scene.add(mesh)
      three.current = { renderer, scene, camera, mesh }
      return () => {
        mesh.geometry.dispose()
        ;(mesh.material as THREE.Material).dispose()
        renderer.dispose()
        three.current = null
      }
    },
    resize(fx) {
      const t = three.current
      if (!t) return
      t.renderer.setPixelRatio(fx.dpr)
      t.renderer.setSize(fx.width, fx.height, false)
      t.camera.aspect = fx.width / fx.height
      t.camera.updateProjectionMatrix()
    },
    frame(fx, dt) {
      const t = three.current
      if (!t) return
      // reduced motion: no idle spin, and the scroll-driven camera and tilt hold
      // their finished pose instead of following the pin (round 10)
      const p = fx.reducedMotion ? 1 : progress.current
      t.mesh.rotation.y += fx.reducedMotion ? 0 : dt * 0.15
      t.mesh.rotation.x = p * Math.PI
      t.camera.position.z = 6 - p * 2.2
      t.renderer.render(t.scene, t.camera)
    },
  })

  return (
    <Track pin={height} onPin={(p) => (progress.current = p)} className={className}>
      <div className="sv-stage" style={{ display: 'grid', placeItems: 'center' }}>
        {/* the cast satisfies React 18's stricter ref types: useCanvasEffect returns
        RefObject<T | null> so the same hook fits React 19 too, and React 18 wants a
        bare RefObject<T> on a host element */}
        <canvas ref={canvasRef as React.RefObject<HTMLCanvasElement>} style={{ width: 'min(90%, 560px)', height: '60vh' }} />
      </div>
    </Track>
  )
}

// ScrollVars fx · split-reveal
// Requires: npm i scrollvars · import 'scrollvars/styles/core.css' (layout)
// <Split> renders word/char spans on the server: no client splitting,
// no CLS, no hydration flash. The full text stays in a visually-hidden span for AT.
'use client'
import * as React from 'react'
import { Reveal, Split } from 'scrollvars/react'

export function SplitReveal({
  children,
  by = 'word',
  stagger = 60,
  className,
}: {
  children: string
  by?: 'word' | 'char'
  stagger?: number
  className?: string
}) {
  return (
    <Reveal once>
      <Split as="h2" by={by} stagger={stagger} className={className ? `sv-split-rise ${className}` : 'sv-split-rise'}>
        {children}
      </Split>
    </Reveal>
  )
}

// ScrollVars fx · rotating-words
// Requires: npm i scrollvars · import 'scrollvars/styles/state.css' (layout)
'use client'
import * as React from 'react'
import { onMotionChange, prefersReducedMotion } from 'scrollvars'

// the rotating column reads as every word in a row to a screen reader, so it
// is aria-hidden and a visually hidden span says the phrase once
const SR: React.CSSProperties = { position: 'absolute', width: 1, height: 1, overflow: 'hidden', clipPath: 'inset(50%)', whiteSpace: 'nowrap' }

export function RotatingWords({
  words,
  interval = 2000,
  className,
}: {
  words: string[]
  interval?: number
  className?: string
}) {
  const [index, setIndex] = React.useState(0)
  // no rotation under reduced motion (the OS setting or the page's switch)
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    setReduced(prefersReducedMotion())
    return onMotionChange(setReduced)
  }, [])
  // A shrinking list strands the last index, same shape as useScenes: clamp
  // here, on the render that sees the new length, instead of waiting for the
  // next tick. An empty list schedules no interval at all: (i + 1) % 0 is
  // NaN, and NaN never recovers ((NaN + 1) % n is NaN for any n), so a list
  // that arrives late, after a tick already fired on an empty one, would
  // stay NaN forever.
  const last = Math.max(words.length - 1, 0)
  if (index > last) setIndex(last)
  const current = Math.min(index, last)
  React.useEffect(() => {
    if (words.length === 0 || reduced) return
    const t = setInterval(() => setIndex((i) => (i + 1) % words.length), interval)
    return () => clearInterval(t)
  }, [words.length, interval, reduced])
  return (
    <>
      <span className={className ? `sv-words ${className}` : 'sv-words'}
        style={{ '--sv-word': current } as React.CSSProperties} aria-hidden="true">
        {words.map((w) => (
          <span key={w}>{w}</span>
        ))}
      </span>
      <span style={SR}>{words.join(', ')}</span>
    </>
  )
}

// ScrollVars fx · pointer-tilt
// Requires: npm i scrollvars · import 'scrollvars/styles/tilt.css' (layout)
// Give each card the sv-tilt class; one delegated listener covers the grid.
'use client'
import * as React from 'react'
import { usePointer } from 'scrollvars/react'

export function PointerTiltGrid({
  children,
  className = 'grid grid-cols-3 gap-6',
}: {
  children: React.ReactNode
  className?: string
}) {
  const ref = usePointer<HTMLDivElement>()
  return (
    // the cast satisfies React 18's stricter ref types: usePointer returns RefObject<T | null> so
    // the same hook fits React 19 too, and React 18 wants a bare RefObject<T> on a host element
    <div ref={ref as React.RefObject<HTMLDivElement>} className={className}>
      {children}
    </div>
  )
}

// ScrollVars fx · coverflow-slider
// Requires: npm i scrollvars · import 'scrollvars/styles/slider.css' (layout)
// Chrome knobs: --sv-arrow-* / --sv-dot-* on this element or :root.
// The CSS below is one constant string injected as raw HTML: React 18's server
// renderer escapes a <style> child (`>` becomes `&gt;`) and <style> is raw text, so
// the entity never decodes and every child-combinator rule is dropped. CSP is
// unchanged from any inline <style>: a style-src nonce or hash, or lift the string
// into your own stylesheet.
'use client'
import * as React from 'react'
import { Slide, Slider } from 'scrollvars/react'

const css = `
.cf-slide { scale: calc(1 - min(max(var(--sd, 0), -1 * var(--sd, 0)) * 0.12, 0.3));
  opacity: calc(1 - min(max(var(--sd, 0), -1 * var(--sd, 0)) * 0.35, 0.7));
  transform: perspective(900px) rotateY(clamp(-24deg, calc(var(--sd, 0) * -16deg), 24deg)); }
@media (prefers-reduced-motion: reduce) { .cf-slide { scale: none; opacity: 1; transform: none; } }
/* the same under html[data-sv-motion="reduce"], the site's own switch */
:where([data-sv-motion="reduce"]) .cf-slide { scale: none; opacity: 1; transform: none; }
`

export function CoverflowSlider({
  children,
  perView = { base: 1.2, md: 2.5, xl: 4 },
  ...rest
}: React.ComponentProps<typeof Slider>) {
  return (
    <>
      {/* the same nonce the Slider gets: under a strict CSP this sheet needs it too */}
      <style nonce={rest.nonce} dangerouslySetInnerHTML={{ __html: css }} />
      <Slider perView={perView} gap={16} arrows dots {...rest}>
        {/* toArray, not Children.map: a conditional child ({show && <Card/>})
            is false, and Children.map still calls back for it, so the rail
            got an empty slide and a dot wired past the end of the engine.
            Anything that is not an element (a portal renders elsewhere) is
            handed to the Slider untouched: it is not a card, and dropping it
            would delete content the caller wrote. */}
        {React.Children.toArray(children).map((child) =>
          React.isValidElement(child) ? (
            <Slide key={child.key} className="cf-slide">
              {child}
            </Slide>
          ) : (
            child
          )
        )}
      </Slider>
    </>
  )
}

