export interface StickyStep {
  title: React.ReactNode
  text?: React.ReactNode
  /** The shot for this step: an <img>, <video>, or any node. */
  media: React.ReactNode
  label?: string
}

// React 19 knows inert as a boolean attribute (a string would be dropped as falsy); React 18
// does not know it and drops booleans, so it gets the empty string instead. Both render inert="".
const INERT = (React.version.startsWith('18') ? { inert: '' } : { inert: true }) as unknown as Record<string, never>

export function StickySteps({ steps, className, nonce }: { steps: StickyStep[]; className?: string; nonce?: string }) {
  // the active index (integer changes only) makes the inactive shots inert, so a
  // crossfaded shot cannot keep focusable links; applied after mount so the
  // server markup stays fully usable without JS
  const status = React.useRef<import('scrollvars').AttachmentStatus>('attaching')
  const flow = React.useRef(true)
  const sync = React.useRef<(() => void) | undefined>(undefined)
  const { ref, scene } = useScenes<HTMLDivElement>(steps.length, {
    // an empty list (a CMS editor removed every step) pins nothing: the stage
    // stays in flow at its natural height instead of a 0vh wrapper
    pin: steps.length ? steps.length * 100 + 'vh' : undefined,
    onStatus: value => { status.current = value; sync.current?.() },
    onFlow: value => { flow.current = value; sync.current?.() },
  })
  const currentScene = React.useRef(scene)
  currentScene.current = scene
  // after mount only (server markup stays fully usable), and never under reduced
  // motion, where the shots stack in flow and must all stay reachable. Live:
  // a switch mid-session drops or restores inert/aria-hidden immediately.
  const [interactive, setInteractive] = React.useState(false)
  useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    // Read the actual layout: failed boot, the watchdog and missing CSS all
    // leave static shots reachable. Only the crossfade hides inactive shots.
    const update = () => {
      const shot = el.querySelector('.st-shot')
      const stage = el.querySelector('.sv-stage')
      // Stack before the driver's first fit read, without hiding shots from AT.
      const empty = !shot
      const measuring = !empty && status.current === 'attaching' && !el.hasAttribute('data-sv-flow') && !prefersReducedMotion()
      let ready = !empty && status.current === 'active' && !flow.current && !prefersReducedMotion()
      if (ready || measuring) el.classList.remove('st-static')
      el.classList.toggle('st-measuring', measuring)
      el.classList.toggle('st-ready', ready)
      ready = ready && !!stage && getComputedStyle(stage).position === 'sticky' &&
        !!shot && getComputedStyle(shot).position === 'absolute'
      const fit = el.querySelector<HTMLElement>('[data-sv-fit]')
      // Keep the candidate's stage constrained until the driver reads overflow.
      // Expanding it here would swallow the fit latch on content replacement.
      const pendingFit = ready && !!fit && Math.max(fit.offsetHeight, fit.scrollHeight) > stage!.clientHeight + 1
      ready = ready && !!fit && Math.max(fit.offsetHeight, fit.scrollHeight) <= stage!.clientHeight + 1
      el.classList.toggle('st-measuring', measuring || pendingFit)
      el.classList.toggle('st-ready', ready)
      el.classList.toggle('st-static', !ready && !pendingFit && (empty || status.current !== 'attaching'))
      el.querySelectorAll('.st-shot').forEach((shot, i) => {
        // Set both directions even when React batches reduce then auto into
        // one render whose interactive state has not changed.
        if (ready && i !== currentScene.current) {
          shot.setAttribute('inert', '')
          shot.setAttribute('aria-hidden', 'true')
        } else {
          shot.removeAttribute('inert')
          shot.removeAttribute('aria-hidden')
        }
      })
      setInteractive(ready)
      // Candidate probing writes classes too. Do not observe our own writes
      // again, especially when missing CSS rejects that candidate.
      observer?.takeRecords()
      if (pendingFit) refreshFit()
    }
    let observer: MutationObserver | undefined
    let stopMotion: (() => void) | undefined
    let stopped = false
    const stop = () => {
      if (stopped) return
      stopped = true
      sync.current = undefined
      const attempt = (fn: () => void) => { try { fn() } catch { /* continue settling this controller */ } }
      attempt(() => observer?.disconnect())
      attempt(() => stopMotion?.())
      attempt(() => el.classList.remove('st-measuring'))
      attempt(() => el.classList.remove('st-ready'))
      attempt(() => el.classList.add('st-static'))
      el.querySelectorAll('.st-shot').forEach(shot => {
        attempt(() => shot.removeAttribute('inert'))
        attempt(() => shot.removeAttribute('aria-hidden'))
      })
      setInteractive(false)
    }
    const fail = (error: unknown) => {
      if (stopped) return
      stop()
      try { console.error('[scrollvars] StickySteps enhancement failed', error) } catch { /* reporting is best effort */ }
    }
    const refresh = () => {
      if (stopped) return
      try { update() } catch (error) { fail(error) }
    }
    sync.current = refresh
    try {
      observer = new MutationObserver(refresh)
      observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] })
      observer.observe(el, { attributes: true, attributeFilter: ['class', 'data-sv-flow'] })
      stopMotion = onMotionChange(refresh)
      if (stopped) { stopMotion(); return stop }
      refresh()
      // The first fit must run next frame, including for an offscreen section.
      if (!stopped && status.current === 'attaching') refreshFit()
    } catch (error) { fail(error) }
    return stop
  }, [ref])
  useLayoutEffect(() => { sync.current?.() }, [scene, steps])
  return (
    <div ref={ref} className={className ? 'sv-steps ' + className : 'sv-steps'}>
      <style nonce={nonce} dangerouslySetInnerHTML={{ __html: css }} />
      <div className="sv-stage"><div data-sv-fit="" className="st-grid">
        <div className="st-media">
          {steps.map((s, i) => (
            <figure
              key={i}
              className="st-shot"
              style={{ '--i': i } as React.CSSProperties}
              {...(interactive && i !== scene ? INERT : {})}
              aria-hidden={interactive && i !== scene ? true : undefined}
            >
              {s.media}
            </figure>
          ))}
        </div>
        <ol className="st-steps">
          {steps.map((s, i) => (
            <li key={i} style={{ '--i': i } as React.CSSProperties}>
              <b>{s.label ?? 'Step ' + (i + 1)}</b>
              <h3>{s.title}</h3>
              {s.text && <p>{s.text}</p>}
            </li>
          ))}
        </ol>
        <div className="st-dots" aria-hidden="true">
          {steps.map((_, i) => (
            <i key={i} style={{ '--i': i } as React.CSSProperties} />
          ))}
        </div>
      </div></div>
    </div>
  )
}

// ScrollVars fx · stats-countup
// Requires: npm i scrollvars · import 'scrollvars/styles/core.css' and 'scrollvars/styles/state.css'
// state.css owns sv-acts; core.css declares --sv-live, and the acts clock is
// calc(var(--sv-live) * var(--sv-acts-count)): without core.css every number
// renders 0 the moment the driver boots.
// Numbers count from zero when the block enters: a CSS counter driven by the
// registered --sv-act transition. No JS, no innerText. Without JS or under
// reduced motion the final numbers render immediately.
// The CSS below is one constant string, injected as raw HTML: a <style> child
// is escaped by React 18's server renderer (`>` becomes `&gt;`, dropping every
// child-combinator rule), and <style> is raw text, so the entity never decodes.
// CSP is unchanged from any inline <style>: allow it with a style-src nonce or
// hash, or lift this string into your own stylesheet.
'use client'
import * as React from 'react'
import { Track } from 'scrollvars/react'

const css = `
.sv-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 18px; margin: 0; }
.sv-stats > div { display: flex; flex-direction: column; padding: 22px 12px; border-radius: 14px; border: 1px solid rgba(128,128,128,.25); text-align: center; }
.sv-stats dt { order: 2; font-size: 13px; margin-top: 8px; opacity: .7; }
.sv-stats dd { margin: 0; font-size: clamp(34px, 6vw, 64px); line-height: 1; font-weight: 800; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.sv-stats .stat { counter-reset: n calc(var(--sv-act, 1) * var(--sv-max)); }
.sv-stats .stat .count::after { content: counter(n) attr(data-suffix); }
html:not(.sv-on) .sv-stats .stat { counter-reset: n var(--sv-max); }
@media (prefers-reduced-motion: reduce) { .sv-stats .stat { counter-reset: n var(--sv-max); } }
:where([data-sv-motion="reduce"]) .sv-stats .stat { counter-reset: n var(--sv-max); }
`

// aria-label is prohibited on generic roles (p/span/div). Axe
// `aria-prohibited-attr`: so the readable text is a visually-hidden child.
const SR_ONLY: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
}

export interface Stat {
  label: React.ReactNode
  value: number
  suffix?: string
}

export function StatsCountup({
  stats,
  duration = 1.8,
  className,
  nonce,
}: {
  stats: Stat[]
  /** Seconds the count takes. */
  duration?: number
  className?: string
  nonce?: string
}) {
  return (
    <Track
      once
      className={className ? 'sv-acts ' + className : 'sv-acts'}
      style={{ '--sv-acts-count': 1, '--sv-acts-duration': duration + 's' } as React.CSSProperties}
    >
      <style nonce={nonce} dangerouslySetInnerHTML={{ __html: css }} />
      <dl className="sv-stats">
        {stats.map((s, i) => (
          <div key={i}>
            <dt>{s.label}</dt>
            {/* both halves sit INSIDE the dd: a dl group takes dt/dd only (a loose
                span there is not in the content model), and a term whose only dd
                is aria-hidden reaches assistive tech with no definition at all */}
            <dd className="stat" style={{ '--sv-max': s.value } as React.CSSProperties}>
              <span style={SR_ONLY}>{s.value}{s.suffix ?? ''}</span>
              <span className="count" data-suffix={s.suffix ?? ''} aria-hidden="true" />
            </dd>
          </div>
        ))}
      </dl>
    </Track>
  )
}

