//
// The projection math below (mask3d-core) is a self-contained, dependency-free
// block: copy it once per project even if you use it in more than one place,
// or lift it into its own module. It is unit-tested on its own upstream
// (test/mask3d-core.test.mjs in the scrollvars repo) before it lands here.
'use client'
import * as React from 'react'
import { onMotionChange, prefersReducedMotion, track } from 'scrollvars'

type Point = [number, number]
type Piece = { contours: Point[][]; depth: number; pivot: Point }
type Pose = { ry?: number; rx?: number; cx?: number; cy?: number; angles?: number[] }
type Bounds = { x0: number; x1: number; y0: number; y1: number }

/**
 * 3D masks, shared projection math (mask3d recipes: word-window, hero-lens,
 * cube-windows). A solid is one or more extruded 2D pieces; each piece turns
 * about its own pivot, then the whole solid turns by a pose (ry, rx) with a
 * perspective focal length. The projected outline becomes a clip-path.
 *
 * Why the union works, kept here for whoever promotes this later: for a
 * closed extruded solid, the projection equals the union of either facing
 * set of its faces. So: both caps normalized to positive area, plus only the
 * side walls whose projected area is positive. A contour's hole (opposite
 * winding to its outer contour, net area 0) survives face-on and gets
 * covered by its own wall once the piece turns far enough to show it edge-on.
 * Nothing emitted is ever negative; the clip-path's nonzero fill rule does
 * the union for you.
 *
 * This file is plain, dependency-free ESM: the recipe's whole point is that
 * you own and edit it. It is unit-tested directly (test/mask3d-core.test.mjs)
 * so a change here proves itself before it goes back into a live page.
 */

function area(poly: Point[]): number {
  let s = 0
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) s += poly[j][0] * poly[i][1] - poly[i][0] * poly[j][1]
  return s / 2
}

// One piece: 2D contours (arrays of [x, y], any winding) extruded to
// `depth`, turning about its own `pivot` ([x, y], default the origin).
function extrude(contours: Point[][], depth: number, pivot: Point = [0, 0]): Piece {
  return { contours, depth, pivot }
}

// Every face of one piece, projected and oriented the same way, appended to
// `out`. `angle` turns the piece about its own pivot; `pose` (ry, rx, cx, cy)
// turns the whole solid about its centre (cx, cy); `focal` is the
// perspective distance. A nonzero fill of everything `faces()` emits, across
// every piece of a solid, is the solid's silhouette.
function faces(piece: Piece, angle: number, pose: Pose, focal: number, out: Point[][] = []): Point[][] {
  const { ry = 0, rx = 0, cx = 0, cy = 0 } = pose
  const cosY = Math.cos(ry), sinY = Math.sin(ry)
  const cosX = Math.cos(rx), sinX = Math.sin(rx)
  const ca = Math.cos(angle), sa = Math.sin(angle)
  // Only the pivot's x turns the piece: it spins about a vertical axis
  // through that point, same as a letter turning in place on the page.
  const [px] = piece.pivot
  const put = (x: number, y: number, z: number): Point => {
    let dx = x - px
    ;[dx, z] = [dx * ca + z * sa, -dx * sa + z * ca]
    let X = px + dx - cx, Y = y - cy, Z = z
    ;[X, Z] = [X * cosY + Z * sinY, -X * sinY + Z * cosY]
    ;[Y, Z] = [Y * cosX - Z * sinX, Y * sinX + Z * cosX]
    const s = focal / (focal + Z)
    return [X * s, Y * s]
  }
  const front = piece.contours.map((c) => c.map(([x, y]) => put(x, y, -piece.depth / 2)))
  const back = piece.contours.map((c) => c.map(([x, y]) => put(x, y, piece.depth / 2)))
  for (const face of [front, back]) {
    const flip = face.reduce((sum, c) => sum + area(c), 0) < 0
    for (const c of face) out.push(flip ? [...c].reverse() : c)
  }
  // Side walls: keep one facing only, that set alone covers the outline.
  front.forEach((c, k) => {
    const b = back[k]
    for (let i = 0; i < c.length; i++) {
      const q = [c[i], c[(i + 1) % c.length], b[(i + 1) % c.length], b[i]]
      if (area(q) > 1e-7) out.push(q)
    }
  })
  return out
}

// The outline of a whole solid (one or more pieces) at one pose. `angles` is
// one turn per piece (default 0), so a recipe can turn letters independently
// of the solid's own pose (word-window's per-letter wave).
function silhouette(pieces: Piece[], pose: Pose, focal: number, angles: number[] = []): Point[][] {
  const out: Point[][] = []
  pieces.forEach((piece, i) => faces(piece, angles[i] ?? 0, pose, focal, out))
  return out
}

// Rounds without toFixed (measured 2x cheaper on the per-frame path).
const r1 = (n: number): number => Math.round(n * 10) / 10

function pathOf(polys: Point[][], ox: number, oy: number, scale: number): string {
  let d = ''
  for (const p of polys) {
    d += 'M'
    for (const [x, y] of p) d += `${r1(ox + x * scale)} ${r1(oy + y * scale)} `
    d += 'Z'
  }
  return d
}

function toClipPath(polys: Point[][], ox: number, oy: number, scale: number): string {
  return `path('${pathOf(polys, ox, oy, scale)}')`
}

// The extent every vertex of `pieces` can reach across `poses` (each a full
// pose plus its own `angles`), so a recipe can fit the solid inside its
// element without cutting a corner off at any reachable turn.
function bounds(pieces: Piece[], poses: Pose[], focal: number): Bounds {
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity
  for (const pose of poses) {
    for (const poly of silhouette(pieces, pose, focal, pose.angles)) {
      for (const [x, y] of poly) {
        x0 = Math.min(x0, x); x1 = Math.max(x1, x)
        y0 = Math.min(y0, y); y1 = Math.max(y1, y)
      }
    }
  }
  return { x0, x1, y0, y1 }
}

// Shape helpers: a box (cube windows), a regular polygon (hex, triangle...),
// a star. All centred on their own pivot.
function box(w: number, h: number, d: number): Piece {
  return extrude([[[-w / 2, -h / 2], [w / 2, -h / 2], [w / 2, h / 2], [-w / 2, h / 2]]], d, [0, 0])
}

function regularPolygon(n: number, r = .5, depth = .3): Piece {
  const c: Point[] = []
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (i * 2 * Math.PI) / n
    c.push([r * Math.cos(a), r * Math.sin(a)])
  }
  return extrude([c], depth, [0, 0])
}

function star(n: number, inner = .45, r = .5, depth = .3): Piece {
  const c: Point[] = []
  for (let i = 0; i < n * 2; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / n
    const rad = i % 2 === 0 ? r : r * inner
    c.push([rad * Math.cos(a), rad * Math.sin(a)])
  }
  return extrude([c], depth, [0, 0])
}

const css = `
.cube-window { position: relative; aspect-ratio: 4 / 3; overflow: hidden; border-radius: 12px; }
.cube-window img, .cube-window video { display: block; width: 100%; height: 100%; object-fit: cover; }
/* no JS / old engines: no clip-path is ever set, so the content stays fully visible */
`

// Same recipe as the CSS tab's mountCubeWindow, in React idiom: an effect
// owns the whole lifecycle (fit, pointer inertia, scroll travel, reduced
// motion, cleanup), the component only renders the box and its content.
function useCubeWindow(ref: React.RefObject<HTMLDivElement | null>, boxSize: [number, number, number], turn: [number, number, number, number]) {
  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    const FOCAL = 2.4, HOVER = { y: .5, x: .35 }, MARGIN = 6, EASE = .12
    const solid = box(...boxSize)
    const [ry0, ry1, rx0, rx1] = turn
    const poseAt = (t: number, hx: number, hy: number): Pose => ({
      ry: ry0 + (ry1 - ry0) * t + hx * HOVER.y,
      rx: rx0 + (rx1 - rx0) * t - hy * HOVER.x,
      cx: 0, cy: 0,
    })

    let t = .5, fit: { w: number; h: number; k: number; ox: number; oy: number } | null = null, last = '', raf = 0
    const hover = { x: 0, y: 0 }, target = { x: 0, y: 0 }

    const refit = () => {
      const w = el.clientWidth, h = el.clientHeight
      if (!w || !h || (fit && fit.w === w && fit.h === h)) return false
      const poses: Pose[] = []
      for (let s = 0; s <= 20; s++)
        for (const hx of [-1, 0, 1]) for (const hy of [-1, 0, 1]) poses.push(poseAt(s / 20, hx, hy))
      const b = bounds([solid], poses, FOCAL)
      const k = Math.min((w - MARGIN * 2) / (b.x1 - b.x0), (h - MARGIN * 2) / (b.y1 - b.y0))
      fit = { w, h, k, ox: w / 2 - ((b.x0 + b.x1) / 2) * k, oy: h / 2 - ((b.y0 + b.y1) / 2) * k }
      return true
    }

    const draw = () => {
      if (!fit) return
      const still = prefersReducedMotion()
      const pose = poseAt(still ? .5 : t, still ? 0 : hover.x, still ? 0 : hover.y)
      const clip = toClipPath(silhouette([solid], pose, FOCAL), fit.ox, fit.oy, fit.k)
      if (clip !== last) { el.style.clipPath = clip; last = clip }
    }

    const settle = () => {
      raf = 0
      hover.x += (target.x - hover.x) * EASE
      hover.y += (target.y - hover.y) * EASE
      draw()
      if (Math.abs(target.x - hover.x) + Math.abs(target.y - hover.y) > .002) raf = requestAnimationFrame(settle)
    }
    const onMove = (e: PointerEvent) => {
      if (prefersReducedMotion()) return
      const r = el.getBoundingClientRect()
      target.x = ((e.clientX - r.left) / r.width) * 2 - 1
      target.y = ((e.clientY - r.top) / r.height) * 2 - 1
      if (!raf) raf = requestAnimationFrame(settle)
    }
    const onLeave = () => { target.x = target.y = 0; if (!raf) raf = requestAnimationFrame(settle) }

    const ro = new ResizeObserver(() => { if (refit()) { last = ''; draw() } })
    ro.observe(el)
    refit()
    draw()
    el.addEventListener('pointermove', onMove)
    el.addEventListener('pointerleave', onLeave)
    const stopMotion = onMotionChange(() => { hover.x = hover.y = target.x = target.y = 0; draw() })
    const stopTrack = track(el, { view: false, onTravel: (v) => { t = v; draw() } })

    return () => {
      stopTrack(); stopMotion(); ro.disconnect()
      el.removeEventListener('pointermove', onMove)
      el.removeEventListener('pointerleave', onLeave)
      if (raf) cancelAnimationFrame(raf)
      el.style.clipPath = ''
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [boxSize[0], boxSize[1], boxSize[2], turn[0], turn[1], turn[2], turn[3]])
}

export function CubeWindows({
  box: boxSize = [.9, .5, .5],
  turn = [-1.4, .35, .8, -.1],
  className,
  children,
  nonce,
}: {
  /** Width, height, depth of the box, as a share of the element's width. */
  box?: [number, number, number]
  /** ry from, ry to, rx from, rx to (radians), across the element's scroll travel. */
  turn?: [number, number, number, number]
  className?: string
  children?: React.ReactNode
  nonce?: string
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  useCubeWindow(ref, boxSize, turn)
  return (
    <div ref={ref} className={className ? 'cube-window ' + className : 'cube-window'}>
      <style nonce={nonce} dangerouslySetInnerHTML={{ __html: css }} />
      {children}
    </div>
  )
}
